<?phpsession_start();require_once "db.php";if (!isset($_SESSION['admin_id'])) {    header("Location: index.php");    exit();}$students = pg_query(    $conn,    "SELECT student_id, roll_number, student_name,            email, course, semester, status     FROM students     ORDER BY student_id DESC");function e($value) {    return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>SmartAttend | Students</title><style>* {    box-sizing: border-box;    font-family: Arial, sans-serif;}body {    margin: 0;    background: #f3f6fc;    color: #263653;}.header {    background: #172b50;    color: white;    padding: 22px 5%;    display: flex;    justify-content: space-between;    align-items: center;}.header h2 {    margin: 0;}.back {    color: white;    text-decoration: none;    background: #5367e8;    padding: 11px 18px;    border-radius: 8px;}.container {    max-width: 1200px;    margin: 40px auto;    padding: 0 20px;}.container h1 {    margin-bottom: 8px;}.subtitle {    color: #8993a5;    margin-bottom: 25px;}.student-card {    background: white;    padding: 25px;    border-radius: 15px;    box-shadow: 0 5px 20px rgba(0,0,0,.05);}.table-responsive {    overflow-x: auto;}table {    width: 100%;    border-collapse: collapse;    min-width: 750px;}th, td {    padding: 15px;    text-align: left;    border-bottom: 1px solid #edf0f5;}th {    background: #edf3ff;    color: #263653;}tr:hover {    background: #f8faff;}.status {    padding: 6px 12px;    border-radius: 20px;    font-size: 12px;    background: #dcfce7;    color: #166534;}.pending {    background: #fef3c7;    color: #92400e;}.rejected {    background: #fee2e2;    color: #991b1b;}@media(max-width:600px) {    .container {        margin-top: 25px;    }    .student-card {        padding: 15px;    }}</style></head><body><header class="header">    <h2>SmartAttend</h2>    <a href="dashboard.php" class="back">Back to Dashboard</a></header><div class="container">    <h1>All Students</h1>    <p class="subtitle">        View all registered student details.    </p>    <div class="student-card">        <div class="table-responsive">            <table>                <tr>                    <th>ID</th>                    <th>Roll Number</th>                    <th>Student Name</th>                    <th>Email</th>                    <th>Course</th>                    <th>Semester</th>                    <th>Status</th>                </tr>                <?php if ($students && pg_num_rows($students) > 0): ?>                    <?php while ($row = pg_fetch_assoc($students)): ?>                    <tr>                        <td><?php echo e($row['student_id']); ?></td>                        <td><?php echo e($row['roll_number']); ?></td>                        <td><?php echo e($row['student_name']); ?></td>                        <td><?php echo e($row['email']); ?></td>                        <td><?php echo e($row['course']); ?></td>                        <td><?php echo e($row['semester']); ?></td>                        <td>                            <span class="status <?php echo e($row['status']); ?>">                                <?php echo e(ucfirst($row['status'])); ?>                            </span>                        </td>                    </tr>                    <?php endwhile; ?>                <?php else: ?>                    <tr>                        <td colspan="7">No students found.</td>                    </tr>                <?php endif; ?>            </table>        </div>    </div></div></body></html>